(function() {
  var SHORTCUTS = {
    'ctrl+n': { action: 'newCard', description: 'Create new card' },
    'ctrl+k': { action: 'search', description: 'Focus search bar' },
    'ctrl+s': { action: 'saveCard', description: 'Save current card' },
    'ctrl+shift+d': { action: 'duplicateCard', description: 'Duplicate current card' },
    'ctrl+j': { action: 'nextCard', description: 'Navigate to next card' },
    'ctrl+shift+j': { action: 'prevCard', description: 'Navigate to previous card' },
    'ctrl+shift+t': { action: 'toggleSidebar', description: 'Toggle sidebar' },
    'escape': { action: 'closePanel', description: 'Close active panel' }
  };

  var isEnabled = true;
  var helpOverlayId = 'cs-shortcut-help';

  function normalizeKeyCombo(e) {
    var parts = [];
    if (e.ctrlKey || e.metaKey) parts.push('ctrl');
    if (e.shiftKey) parts.push('shift');
    if (e.altKey) parts.push('alt');
    var key = e.key.toLowerCase();
    if (key !== 'control' && key !== 'shift' && key !== 'alt' && key !== 'meta') {
      parts.push(key);
    }
    return parts.join('+');
  }

  function dispatchAction(actionName) {
    console.log('[Productivity Kit] Dispatching action:', actionName);
    document.dispatchEvent(new CustomEvent('cardspoke:action', {
      detail: { action: actionName }
    }));
  }

  function handleKeyDown(e) {
    if (!isEnabled) return;
    var inputTags = ['INPUT', 'TEXTAREA', 'SELECT'];
    if (inputTags.indexOf(e.target.tagName) !== -1 && e.key !== 'Escape') return;
    var combo = normalizeKeyCombo(e);
    if (combo === 'ctrl+shift+/') {
      e.preventDefault();
      toggleHelpOverlay();
      return;
    }
    var shortcut = SHORTCUTS[combo];
    if (shortcut) {
      e.preventDefault();
      dispatchAction(shortcut.action);
    }
  }

  function createHelpOverlay() {
    var overlay = document.createElement('div');
    overlay.id = helpOverlayId;
    overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.6);z-index:10001;display:flex;align-items:center;justify-content:center;';
    var content = '<div style="background:#fff;border-radius:12px;padding:24px 30px;max-width:420px;width:90%;box-shadow:0 10px 40px rgba(0,0,0,0.2);"><h3 style="margin:0 0 16px;font-size:16px;color:#333;">Keyboard Shortcuts</h3><table style="width:100%;border-collapse:collapse;">';
    var keys = Object.keys(SHORTCUTS);
    for (var i = 0; i < keys.length; i++) {
      var key = keys[i];
      var desc = SHORTCUTS[key].description;
      var displayKey = key.replace(/ctrl/g, 'Ctrl').replace(/shift/g, 'Shift').replace(/alt/g, 'Alt').replace(/\+/g, ' + ');
      content += '<tr style="border-bottom:1px solid #f0f0f0;"><td style="padding:6px 0;font-size:13px;color:#666;">' + desc + '</td><td style="padding:6px 0;text-align:right;"><kbd style="background:#f5f5f5;border:1px solid #ddd;border-radius:3px;padding:2px 6px;font-size:12px;font-family:monospace;color:#333;">' + displayKey + '</kbd></td></tr>';
    }
    content += '</table><p style="margin:12px 0 0;font-size:11px;color:#999;">Press Ctrl+Shift+/ to toggle this help.</p></div>';
    overlay.innerHTML = content;
    overlay.addEventListener('click', function(e) {
      if (e.target === overlay) toggleHelpOverlay();
    });
    return overlay;
  }

  function toggleHelpOverlay() {
    var existing = document.getElementById(helpOverlayId);
    if (existing) {
      existing.parentNode.removeChild(existing);
    } else {
      document.body.appendChild(createHelpOverlay());
    }
  }

  function cleanup() {
    isEnabled = false;
    document.removeEventListener('keydown', handleKeyDown);
    var overlay = document.getElementById(helpOverlayId);
    if (overlay) overlay.parentNode.removeChild(overlay);
  }

  CardSpoke_MODS.register({
    name: 'Productivity Kit',
    hooks: {
      onAppInit: function() {
        document.addEventListener('keydown', handleKeyDown);
        console.log('[Productivity Kit] Initialized with', Object.keys(SHORTCUTS).length, 'shortcuts. Press Ctrl+Shift+/ for help.');
      },
      onDisable: function() {
        cleanup();
        console.log('[Productivity Kit] Disabled, shortcuts removed');
      }
    }
  });
})()

