:root {
  --bg-primary: #f5f6f8;
  --bg-card: #ffffff;
  --bg-hover: #eef0f4;
  --text-primary: #1a1a2e;
  --text-secondary: #5a5a7a;
  --accent-primary: #3b6fd4;
  --accent-border: #d8dce6;
}

.cs-card {
  background: var(--bg-card);
  border: 1px solid var(--accent-border);
  border-radius: 6px;
  padding: 16px;
  transition: border-color 0.15s ease;
}

.cs-card:hover {
  border-color: var(--accent-primary);
}

.cs-card:focus-within {
  box-shadow: 0 0 0 2px rgba(59, 111, 212, 0.2);
}

.cs-sidebar {
  background: var(--bg-primary);
  border-right: 1px solid var(--accent-border);
}

.cs-input:focus {
  border-color: var(--accent-primary);
  outline: none;
}

kbd {
  background: var(--bg-hover);
  border: 1px solid var(--accent-border);
  border-radius: 3px;
  padding: 1px 5px;
  font-size: 0.85em;
  font-family: monospace;
}
